'use strict';
const M=window.PlannerModel;
const TODAY=new Intl.DateTimeFormat('en-CA',{timeZone:'America/Bogota',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());
const KEY='mi-dia.pastel-v2.demo';
const $=s=>document.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let state=M.seed(TODAY),page='agenda',view='day',date=TODAY,company='all',mode='list',goalLevel='five',goalFocus=null,agendaGoal=null,goalsView='structure',slotMinutes=30,executorFilter='all',toastTimer;
try{const loaded=JSON.parse(localStorage.getItem(KEY));if(M.validState(loaded))state=loaded;}catch{}
M.upgrade(state);
const C=id=>state.companies[id]||state.companies.PER;
const uid=()=>typeof crypto.randomUUID==='function'?crypto.randomUUID():Array.from(crypto.getRandomValues(new Uint32Array(4)),n=>n.toString(16)).join('-');
const entryDrafts=new Map(), timelinePositions=new Map();
let projectReturn='list',pendingImport=null;
function notebookContext(){return {state,model:M,date,today:TODAY,company,view,executorFilter,mode,step:slotMinutes,onDate,filteredTasks,esc,tag,companyStyle,shortDate,dayName,goalMini,habitItem,inlineRoutine,drafts:entryDrafts};}
const companyStyle=id=>`--company:${C(id).color};--company-bg:${C(id).bg}`;
const shortDate=d=>M.dateObject(d).toLocaleDateString('es-CO',{day:'numeric',month:'short',timeZone:'UTC'}).replace(' de ',' ');
const dayName=d=>M.dateObject(d).toLocaleDateString('es-CO',{weekday:'long',timeZone:'UTC'});
function notify(text){const open=[...document.querySelectorAll('dialog[open]')].at(-1);(open||document.body).append($('#toast'));$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3200);}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));$('#save-status').textContent='Guardado solo en este navegador';}catch{$('#save-status').textContent='Sin guardado local: los cambios se perderán al cerrar';}}
function companyOptions(selected,all=false){return `${all?'<option value="all">Todos</option>':''}${Object.entries(state.companies).map(([id,c])=>`<option value="${esc(id)}" ${selected===id?'selected':''}>${esc(c.name)}</option>`).join('')}`;}
function tag(id){return `<span class="company-tag" title="${esc(C(id).name)}" style="${companyStyle(id)}">@${esc(M.handle(C(id).name))}</span>`;}
function filteredTasks(){const ids=agendaGoal?M.descendants(state.goals,agendaGoal):null;return state.tasks.filter(t=>!t.cancelledBySeries&&(company==='all'||t.company===company)&&(!ids||ids.has(t.goalId))&&(page!=='agenda'||state.calendars.find(c=>c.id===t.calendarId)?.visible!==false));}
function calendarChecks(){return state.calendars.map(c=>`<label class="calendar-check"><input type="checkbox" class="check" data-calendar-visible="${esc(c.id)}" ${c.visible?'checked':''}>${esc(c.title)}</label>`).join('');}
function recordCompletion(task,done){if(task.done!==done){state.completionEvents.push({taskId:task.id,done,company:task.company,title:task.title,time:task.time||'',on:TODAY,at:new Date().toISOString()});task.done=done;}}
function renderGrowth(){const first=M.addDays(M.monday(date),-21);return `<div class="growth-wrapper"><p class="subtle" style="margin:0 0 20px;line-height:1.8">Actividad registrada en esta demo. No mide ingresos ni resultados de negocio. Las semanas sin registros quedan en cero.</p><table class="growth-table"><thead><tr><th>Semana</th><th>Tareas hechas</th><th>Hábitos marcados</th></tr></thead><tbody>${Array.from({length:4},(_,i)=>{const start=M.addDays(first,i*7),end=M.addDays(start,6),habits=Object.entries(state.habitChecks).filter(([key,done])=>done&&key.slice(0,10)>=start&&key.slice(0,10)<=end).length;return `<tr><td>${shortDate(start)} – ${shortDate(end)}</td><td>${M.activity(state,start,end,company)}</td><td>${company==='all'||company==='PER'?habits:'—'}</td></tr>`;}).join('')}</tbody></table><p class="origin">Tareas: última marca de completado por tarea; al deshacerla deja de contar. Hábitos personales: marcas por fecha. No hay actividad histórica importada.</p></div>`;}
function renderFinance(){return '<section class="future-panel"><h2>Finanzas personales · Para después</h2><p>Cuando activemos esta sección, podrás añadir tus servicios, suscripciones y categorías uno a uno. No se han importado pagos de Ohros ni de Drive.</p><small>Dar de baja detendrá las próximas renovaciones. Los meses anteriores conservarán su historial; que llegue la fecha no marcará un pago como realizado.</small></section>';}
function extraHours(){return '';}
const onDate=d=>filteredTasks().filter(t=>t.date===d).sort((a,b)=>(a.time||'99').localeCompare(b.time||'99'));
function taskCard(t,kind='task-card'){return NotebookView.taskRow(t,notebookContext(),kind);}
function addLine(d,time='',quadrant=2){return NotebookView.quickLine(d,notebookContext(),time,quadrant);}
function habitCheck(h,d){return !!state.habitChecks[`${d}|${h.id}`];}
function habitItem(h,d){const done=habitCheck(h,d);return `<label class="habit-item ${done?'done':''}"><input type="checkbox" class="check" data-habit-check="${esc(h.id)}" data-habit-date="${esc(d)}" ${done?'checked':''} aria-label="${esc(h.title)} ${esc(d)}"><span>${esc(h.title)}${h.company&&h.company!=='PER'?'<small class="habit-business">'+tag(h.company)+'</small>':''}</span>${h.time?`<small>${esc(M.formatTime12(h.time))}</small>`:''}</label>`;}
function inlineRoutine(d){const habits=state.habits.filter(h=>M.habitDue(h,d)),done=habits.filter(h=>habitCheck(h,d)).length;return `<details class="routine-inline"><summary>Rutina <span>${done}/${habits.length}</span></summary>${habits.map(h=>habitItem(h,d)).join('')}</details>`;}
function weekNotesKey(){return 'week-'+M.monday(date);}
function weekSummary(){return NotebookView.summary(notebookContext());}
function goalMini(g){const p=M.progress(state,g.id);return `<button class="goal-mini" data-open-goal="${esc(g.id)}"><span class="name">${esc(g.title)}</span><span class="task-meta">${tag(g.company)}</span><div class="progress-line" style="--progress:${p.percent}%"><i></i></div><small>${p.total?`${p.done}/${p.total} tareas hechas`:'Sin tareas vinculadas'}</small></button>`;}
function renderWeek(){return NotebookView.week(notebookContext());}
function hourSlot(d,h,tasks){return tasks.map(t=>taskCard(t,'timed-task')).join('')+addLine(d,String(h).padStart(2,'0')+':00');}
function renderDay(){return NotebookView.day(notebookContext());}
function renderWeekHours(start){return NotebookView.weekHours(start,notebookContext());}
function renderMonth(){const first=date.slice(0,7)+'-01',start=M.monday(first),count=Math.ceil(((M.dateObject(first).getUTCDay()+6)%7+M.daysOfMonth(date))/7)*7;return `<section class="month-board"><div class="month-weekdays">${['Lun','Mar','Mié','Jue','Vie','Sáb','Dom'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-days">${Array.from({length:count},(_,i)=>{const d=M.addDays(start,i),tasks=onDate(d);return `<div class="month-cell ${d.slice(0,7)!==date.slice(0,7)?'outside':''}" data-drop-date="${d}"><button data-open-day="${d}" class="month-date ${d===TODAY?'today':''}" aria-label="Abrir ${d}">${Number(d.slice(-2))}</button>${tasks.slice(0,3).map(t=>`<button class="month-task" data-open-task="${esc(t.id)}" style="${companyStyle(t.company)}">${t.time?esc(M.formatTime12(t.time))+' ':''}${esc(t.title)}</button>`).join('')}${tasks.length>3?`<button class="more-tasks" data-open-day="${d}">+${tasks.length-3}</button>`:''}</div>`;}).join('')}</div></section>`;}
function renderGoals(){const focus=state.goals.find(g=>g.id===goalFocus),parentTasks=focus?state.tasks.filter(t=>M.descendants(state.goals,focus.id).has(t.goalId)):[];const [start,end]=M.periodBounds(goalLevel,date);const goals=state.goals.filter(g=>(company==='all'||g.company===company)&&(focus?g.parentId===focus.id:g.level===goalLevel&&g.end>=start&&g.start<=end));return `<div class="goals-top">${M.levels.map(level=>`<button class="period-pill ${goalLevel===level&&!focus?'active':''}" data-level="${level}">${M.levelNames[level]}</button>`).join('')}</div>${!focus?'<div class="goal-path-hint"><strong>5 años</strong> → Año → Trimestre → Mes → Semana → Día → Horas</div>':''}<div class="goal-grid">${goals.map(g=>{const p=M.progress(state,g.id),children=state.goals.filter(x=>x.parentId===g.id);return `<article class="goal-card" style="${companyStyle(g.company)}"><button class="goal-card-top" data-open-goal="${esc(g.id)}">${tag(g.company)}<h2>${esc(g.title)}</h2><div class="goal-description">${M.levelNames[g.level]} · ${g.example?'Ejemplo':'Tu meta'}</div><div class="progress-line" style="--progress:${p.percent}%"><i></i></div><div class="goal-meta"><span>${p.total?`${p.done}/${p.total} tareas`:'Sin tareas vinculadas'}</span><span>${shortDate(g.end)} ${g.end.slice(0,4)}</span></div></button><div class="goal-card-actions"><button data-open-goal="${esc(g.id)}">${g.level==='week'?'Ver tareas':`Ver ${children.length} ${children.length===1?'meta':'metas'}`} <span>→</span></button><button data-edit-goal="${esc(g.id)}" aria-label="Editar meta ${esc(g.title)}">Editar</button></div></article>`;}).join('')}${!focus||focus.level!=='week'?`<button class="add-goal-card" id="add-goal-card">＋ Añadir meta</button>`:''}</div>${focus?`<div class="goal-tasks"><div class="section-heading"><h2>Tareas vinculadas</h2><button class="text-button" data-goal-agenda="${esc(focus.id)}">Ver en agenda →</button></div>${parentTasks.map(t=>taskCard(t)).join('')||'<p class="empty">Todavía no hay tareas vinculadas a esta meta.</p>'}<button class="quiet-button" data-add-goal-task="${esc(focus.id)}">＋ Vincular una tarea</button></div>`:''}${!goals.length&&!focus?'<p class="empty">Añade tu meta. Las cifras y objetivos los defines tú.</p>':''}`;}
function renderHabits(){const start=M.monday(date),suggestions=M.routineSuggestions(state);return `<div class="habit-week-strip">${Array.from({length:7},(_,i)=>{const d=M.addDays(start,i);return `<button data-habit-day="${d}" class="${date===d?'active':''}">${dayName(d).slice(0,3)}<strong>${Number(d.slice(-2))}</strong></button>`;}).join('')}</div><div class="habits-layout">${[['morning','Mañana'],['anytime','Durante el día'],['night','Noche']].map(([group,title])=>`<section class="habit-group"><h2>${title}</h2>${state.habits.filter(h=>h.group===group&&M.habitDue(h,date)).map(h=>habitItem(h,date)).join('')}<button class="habit-add" data-add-habit="${group}">＋ Añadir hábito</button></section>`).join('')}</div><details class="routine-proposals notebook-context"><summary>Propuestas por repetición · ${suggestions.length}</summary><p class="origin">Regla local: una tarea completada en al menos tres fechas distintas. No es una IA conectada. Tú decides si se vuelve rutina.</p>${suggestions.map((h,i)=>`<div class="project-row"><div><strong>${esc(h.title)}</strong><small>${tag(h.company)} · ${h.count} fechas registradas</small></div><button class="quiet-button" data-suggest-habit="${i}">Revisar propuesta</button></div>`).join('')||'<p class="empty">Todavía no hay repeticiones suficientes.</p>'}</details>`;}
function renderMini(){const first=date.slice(0,7)+'-01',start=M.monday(first),count=Math.ceil(((M.dateObject(first).getUTCDay()+6)%7+M.daysOfMonth(date))/7)*7;$('#mini-calendar').innerHTML=`<div class="mini-month-head"><span>${M.dateObject(date).toLocaleDateString('es-CO',{month:'long',year:'numeric',timeZone:'UTC'})}</span></div><div class="mini-calendar">${['L','M','X','J','V','S','D'].map(x=>`<span class="mini-day-label">${x}</span>`).join('')}${Array.from({length:count},(_,i)=>{const d=M.addDays(start,i);return `<button data-open-date="${d}" class="${d===TODAY?'today':''} ${d===date?'selected':''} ${d.slice(0,7)!==date.slice(0,7)?'outside':''}" aria-label="Ir a ${d}">${Number(d.slice(-2))}</button>`;}).join('')}</div>`;}
function periodTitle(){if(page==='finance')return 'Finanzas';if(page==='goals'){const g=state.goals.find(g=>g.id===goalFocus);return goalsView==='growth'?'Avance':g?'Metas':`Metas · ${date.slice(0,4)}`;}if(page==='habits')return `Rutinas · ${shortDate(date)}`;if(page==='decisions')return 'Decisiones';if(view==='matrix')return 'Matriz';if(view==='day')return `${dayName(date).slice(0,1).toUpperCase()+dayName(date).slice(1)} ${shortDate(date)}`;if(view==='month')return M.dateObject(date).toLocaleDateString('es-CO',{month:'long',year:'numeric',timeZone:'UTC'});const start=M.monday(date),end=M.addDays(start,6);return `${Number(start.slice(-2))}–${shortDate(end)} ${end.slice(0,4)}`;}
function render(){
  if(page==='agenda'){
    const bounds=view==='week'?[M.monday(date),M.addDays(M.monday(date),6)]:view==='month'?[M.monday(date.slice(0,7)+'-01'),M.addDays(date.slice(0,7)+'-'+M.daysOfMonth(date),7)]:[date,date];
    if(M.materializeRecurrences(state,...bounds))save();
  }
  const oldTimeline=$('#day-agenda')||$('#week-hours');if(oldTimeline?.dataset.scrollKey)timelinePositions.set(oldTimeline.dataset.scrollKey,oldTimeline.scrollTop);
  $('#period-title').textContent=periodTitle();document.title=`Juan Pablo Merizalde · ${page==='finance'?'Finanzas':page==='agenda'?'Agenda':page==='goals'?'Metas':page==='habits'?'Rutinas':'Decisiones'}`;
  document.querySelectorAll('[data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));
  document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',b.dataset.view===view);});
  $('#view-tabs').hidden=page!=='agenda';$('#add-main').innerHTML=page==='goals'?'＋ <span>Meta</span>':page==='habits'?'＋ <span>Hábito</span>':'＋ <span>Tarea</span>';
  $('#add-main').setAttribute('aria-label',page==='goals'?'Añadir meta':page==='habits'?'Añadir hábito':'Añadir tarea');
  $('#add-main').hidden=page==='finance'||page==='goals'&&goalsView==='growth';
  for(const id of ['previous-period','go-today','next-period'])$('#'+id).hidden=page==='finance'||page==='agenda'&&view==='matrix';
  $('#internal-calendars').innerHTML=calendarChecks();
  $('#company-list').innerHTML=`<button class="company-button ${company==='all'?'selected':''}" data-company="all"><span style="width:7px;text-align:center;color:#9aa991">◫</span> Todos</button>${Object.entries(state.companies).map(([id,c])=>`<button class="company-button ${company===id?'selected':''}" data-company="${esc(id)}" style="${companyStyle(id)}"><span class="company-dot"></span>${esc(c.name)}</button>`).join('')}`;
  $('#mobile-company').innerHTML=companyOptions(company,true)+'<option value="__new__">＋ Negocio</option><option value="__projects__">Proyectos…</option><option value="__import__">Importar…</option><option value="__repeats__">Tareas recurrentes…</option>';
  $('#decision-count').textContent=filteredTasks().filter(t=>t.decision&&!t.done).length;
  let left=company==='all'?'':`<button class="text-button" data-edit-company="${esc(company)}">${tag(company)} · Editar negocio</button>`;
  const focus=state.goals.find(g=>g.id===goalFocus);
  if(page==='goals'&&focus){left=`<div class="crumbs"><button data-goal-root="true">Metas</button>${M.goalTrail(state.goals,focus.id).map(g=>`<span>›</span><button data-open-goal="${esc(g.id)}">${esc(g.title)}</button>`).join('')}</div>`;}
  if(page==='agenda'&&agendaGoal){const goal=state.goals.find(g=>g.id===agendaGoal);left=`<span class="subtle">Meta: ${esc(goal?.title||'')}</span><button class="text-button" id="clear-goal-filter">Quitar filtro ×</button>`;}
  const right=page==='agenda'?`<div class="agenda-options"><details class="mobile-calendars"><summary>Calendarios</summary><div>${calendarChecks()}<button class="text-button" id="mobile-add-calendar">＋ Calendario</button></div></details>${view==='week'?`<div class="view-mode"><button data-mode="list" class="${mode==='list'?'active':''}">Lista</button><button data-mode="hours" class="${mode==='hours'?'active':''}">Horas</button></div>`:''}${view==='day'||view==='week'&&mode==='hours'?`<div class="view-mode" aria-label="Tamaño del renglón"><button data-slot-minutes="30" class="${slotMinutes===30?'active':''}">30 min</button><button data-slot-minutes="60" class="${slotMinutes===60?'active':''}">1 hora</button></div>`:''}${view==='matrix'?`<label class="executor-filter">Responsable <select id="executor-filter"><option value="all" ${executorFilter==='all'?'selected':''}>Todos</option><option value="self" ${executorFilter==='self'?'selected':''}>Yo</option><option value="human" ${executorFilter==='human'?'selected':''}>Humano</option><option value="ai" ${executorFilter==='ai'?'selected':''}>IA · Sin ejecutar</option></select></label>`:''}</div>`:page==='goals'?`<div class="view-mode"><button data-goals-view="structure" class="${goalsView==='structure'?'active':''}">Metas</button><button data-goals-view="growth" class="${goalsView==='growth'?'active':''}">Avance</button></div>`:'';
  $('#sub-toolbar').innerHTML=`<div class="sub-toolbar"><div class="left">${left}</div>${right}</div>`;
  $('#content').innerHTML=page==='finance'?renderFinance():page==='agenda'?(view==='week'?renderWeek():view==='day'?renderDay():view==='matrix'?NotebookView.matrix(notebookContext()):renderMonth())+((view==='day'||view==='week'&&mode==='hours')?extraHours():''):page==='goals'?(goalsView==='growth'?renderGrowth():renderGoals()):page==='habits'?renderHabits():`<div class="decisions-list">${filteredTasks().filter(t=>t.decision&&!t.done).map(t=>taskCard(t)).join('')||'<p class="empty">Sin decisiones pendientes.</p>'}<button class="text-button" id="new-decision">＋ Añadir decisión</button></div>`;
  if(page==='agenda'&&view!=='matrix'){const undated=filteredTasks().filter(t=>!t.date);if(undated.length)$('#content').insertAdjacentHTML('beforeend',`<details class="extra-hours"><summary>Sin fecha · ${undated.length}</summary>${undated.map(t=>taskCard(t)).join('')}</details>`);}
  renderMini();document.querySelectorAll('.line-title').forEach(resizeLine);const timeline=$('#day-agenda')||$('#week-hours');if(timeline){const key=[date,view,mode,slotMinutes].join('|');timeline.dataset.scrollKey=key;const start=timeline.querySelector('[data-slot-time="07:00"]');timeline.scrollTop=timelinePositions.has(key)?timelinePositions.get(key):start?start.offsetTop:0;}
  if(view==='week'&&page==='agenda'&&mode==='list'&&window.innerWidth<600){const wrap=$('#week-wrap'),column=wrap?.querySelector(`[data-drop-date="${date}"]`);if(column)wrap.scrollLeft=column.offsetLeft-wrap.offsetLeft-16;}
}
function updateTaskFields(){const companyId=$('#task-company').value,oldGoal=$('#task-goal').value,oldProject=$('#task-project').value;$('#task-goal').innerHTML='<option value="">Sin vincular</option>'+state.goals.filter(g=>g.company===companyId).map(g=>`<option value="${esc(g.id)}">${M.levelNames[g.level]} · ${esc(g.title)}</option>`).join('');$('#task-goal').value=oldGoal;$('#task-project').innerHTML='<option value="">Sin proyecto</option>'+state.projects.filter(p=>p.company===companyId&&(!p.status||p.status==='active'||p.id===state.tasks.find(t=>t.id===$('#task-id').value)?.projectId)).map(p=>`<option value="${esc(p.id)}">${esc(p.title)}</option>`).join('')+'<option value="__new__">＋ Añadir proyecto</option>';$('#task-project').value=state.projects.some(p=>p.id===oldProject&&p.company===companyId)?oldProject:'';updateGoalTrail();}
function updateGoalTrail(){const id=$('#task-goal').value;$('#goal-trail').textContent=id?M.goalTrail(state.goals,id).map(g=>`${M.levelNames[g.level]}: ${g.title}`).join(' › '):'';}
function openTask(id=null,options={}){const task=state.tasks.find(t=>t.id===id);$('#task-form').reset();$('#task-id').value=task?.id||'';$('#task-title').value=task?.title||'';$('#task-company').innerHTML=companyOptions(task?.company||(company==='all'?'PER':company));$('#task-date').value=task?(task.date||''):(options.date||date);$('#task-time').value=M.formatTime12(task?.time||options.time||'');$('#task-calendar').innerHTML=state.calendars.map(c=>`<option value="${esc(c.id)}">${esc(c.title)}</option>`).join('');$('#task-calendar').value=task?.calendarId||state.calendars.find(c=>c.visible)?.id||'main';updateTaskFields();$('#task-project').value=task?.projectId||'';$('#task-goal').value=task?.goalId||options.goalId||'';updateGoalTrail();$('#task-priority').value=task?.priority?'1':'0';$('#task-quadrant').value=task?.quadrant||2;$('#task-decision').value=task?.decision||options.decision?'1':'0';$('#task-kind-label').textContent=task?.decision?'Decisión':'Tarea';$('#task-options').value=task?.options||'';$('#task-executor').value=task?.executor||'self';$('#task-assignee').value=task?.assignee||'';$('#task-result').value=task?.expectedResult||'';$('#task-actual').value=task?.actualResult||'';$('#task-reversible').value=task?.decisionType||'';$('#task-duration').value=task?.duration||30;$('#task-notes').value=task?.notes||'';configureRepeatCard(task);$('#task-origin').textContent=task?.origin||'Nueva tarea de demostración · Sin acciones externas';$('#task-error').textContent='';$('#task-complete').hidden=!task;$('#task-complete').textContent=task?.done?'Marcar pendiente':'Marcar hecha';$('#task-more').open=!!task?.decision;$('#task-dialog').showModal();$('#task-title').focus();}
function saveTask(toggle=false){const id=$('#task-id').value,old=state.tasks.find(t=>t.id===id);const task={id:id||uid(),title:$('#task-title').value.trim(),company:$('#task-company').value,date:$('#task-date').value||null,time:M.parseTime12($('#task-time').value),duration:+$('#task-duration').value||30,projectId:$('#task-project').value,goalId:$('#task-goal').value||null,priority:$('#task-priority').value==='1',quadrant:+$('#task-quadrant').value,decision:$('#task-decision').value==='1',options:$('#task-options').value,notes:$('#task-notes').value,done:toggle?!old?.done:!!old?.done,origin:old?.origin||'Creada en esta demo'};
  task.calendarId=$('#task-calendar').value;task.executor=$('#task-executor').value;task.assignee=$('#task-assignee').value.trim();task.expectedResult=$('#task-result').value.trim();task.actualResult=$('#task-actual').value.trim();task.decisionType=$('#task-reversible').value;const parsed=M.parseEntry(task.title,state,task.company);applyParsed(task,parsed);
  const repeat=parsed.repeat||repeatFromCard();let error=(!old&&state.tasks.length>=20000?'La libreta alcanzó el límite local. Exporta una copia.':'')||(old?.seriesId&&parsed.repeat?'Esta tarea ya es recurrente. Los cambios de texto son solo para esta fecha.':repeat&&!task.date?'Elige una fecha de inicio para repetir.':'')||parsed.error||(!task.title?'Escribe el título.':M.priorityError(state.tasks,task));const goal=state.goals.find(g=>g.id===task.goalId),project=state.projects.find(p=>p.id===task.projectId);if(goal&&goal.company!==task.company)error='La meta debe ser del mismo negocio.';if(project&&project.company!==task.company)error='El proyecto debe ser del mismo negocio.';if(task.projectId==='__new__')error='Crea o elige el proyecto.';if(task.time===null)error='Escribe la hora en formato de 12 horas: 9:30 AM o 2:30 PM.';if(task.time&&!task.date)error='Asigna una fecha al horario.';if(error){$('#task-error').textContent=error;return false;}if(old){const nextDone=task.done;task.done=old.done;Object.assign(old,task);recordCompletion(old,nextDone);}else state.tasks.push(task);if(repeat&&!old?.seriesId)M.addRecurrence(state,old||task,repeat,uid());save();$('#task-dialog').close();render();return true;}
function parentOptions(){const id=$('#goal-id').value,c=$('#goal-company').value,l=$('#goal-level').value,old=$('#goal-parent').value;$('#goal-parent').innerHTML='<option value="">Sin meta superior</option>'+state.goals.filter(g=>g.id!==id&&g.company===c&&M.levels.indexOf(g.level)<M.levels.indexOf(l)&&!M.descendants(state.goals,id).has(g.id)).map(g=>`<option value="${esc(g.id)}">${M.levelNames[g.level]} · ${esc(g.title)}</option>`).join('');$('#goal-parent').value=old;}
function openGoalForm(id=null){const goal=state.goals.find(g=>g.id===id),parent=goal?null:state.goals.find(g=>g.id===goalFocus);$('#goal-form').reset();$('#goal-id').value=goal?.id||'';$('#goal-title').value=goal?.title||'';$('#goal-company').innerHTML=companyOptions(goal?.company||parent?.company||(company==='all'?'PER':company));const level=goal?.level||(parent?M.levels[M.levels.indexOf(parent.level)+1]||'week':goalLevel);$('#goal-level').innerHTML=M.levels.map(l=>`<option value="${l}">${M.levelNames[l]}</option>`).join('');$('#goal-level').value=level;parentOptions();$('#goal-parent').value=goal?.parentId||parent?.id||'';const bounds=M.periodBounds(level,date);$('#goal-start').value=goal?.start||bounds[0];$('#goal-end').value=goal?.end||bounds[1];$('#goal-notes').value=goal?.notes||'';$('#goal-error').textContent='';$('#goal-dialog').showModal();$('#goal-title').focus();}
function openHabit(group='morning'){$('#habit-form').reset();$('#habit-time').value='';$('#habit-company').innerHTML=companyOptions(company==='all'?'PER':company);$('#habit-group').value=group;$('#habit-days').innerHTML=['L','M','X','J','V','S','D'].map((name,i)=>`<label><input type="checkbox" value="${i}" checked name="days" aria-label="${['Lunes','Martes','Miércoles','Jueves','Viernes','Sábado','Domingo'][i]}"><span>${name}</span></label>`).join('');$('#habit-error').textContent='';$('#habit-dialog').showModal();$('#habit-title').focus();}
const palette=[['#4d7f4c','#e5f0db'],['#7d629e','#efe5f7'],['#507ba0','#e5eef7'],['#a36a3a','#f9ebd8'],['#ad677f','#f7e5ec'],['#8c7a33','#f2efd8']];
function openCompany(id=null){const c=state.companies[id];$('#company-form').reset();$('#company-id').value=id||'';$('#company-name').value=c?.name||'';$('#company-role').value=c?.role||'';$('#company-platform').value=c?.platform||'';$('#company-url').value=c?.url||'';$('#company-context').value=c?.context||'';$('#company-colors').innerHTML=palette.map(([color,bg],i)=>`<label><input type="radio" name="color" value="${i}" ${color===(c?.color||palette[0][0])?'checked':''} required aria-label="Color ${i+1}"><span style="background:${bg};border-color:${color}"></span></label>`).join('');$('#company-dialog').showModal();$('#company-name').focus();}
function openProject(id=null){const p=state.projects.find(p=>p.id===id);projectReturn=$('#task-dialog').open?'task':'list';$('#projects-dialog').close();$('#project-form').reset();$('#project-id').value=p?.id||'';$('#project-title').value=p?.title||'';$('#project-company').innerHTML=companyOptions(p?.company||(projectReturn==='task'?$('#task-company').value:company==='all'?'PER':company));$('#project-status').value=p?.status||'active';$('#project-dialog').showModal();$('#project-title').focus();}
function openConnections(){const base=[['Google Calendar','Varias cuentas · Reuniones, disponibilidad y bloques. Requiere autorización por cuenta.','GC'],['Gmail','Correos como candidatos a tarea','G'],['Claude','Planificación con tu contexto autorizado','C'],['VIUU · Lovable','Pendientes y decisiones de la plataforma','V'],['Moobi · Transporte','Pendientes y decisiones de tu plataforma','M']];$('#connections-list').innerHTML=base.map(([name,desc,icon])=>`<div class="connection-row"><span class="connection-icon">${icon}</span><div><h3>${name}</h3><p>${desc}</p></div><span>Sin conectar</span></div>`).join('')+Object.values(state.companies).filter(c=>c.platform).map(c=>`<div class="connection-row"><span class="connection-icon">↗</span><div><h3>${esc(c.name)} · ${esc(c.platform)}</h3><p>Referencia guardada${c.url?' · '+esc(c.url):''}</p></div><span>Sin sincronizar</span></div>`).join('');$('#connections-dialog').showModal();}
function changePeriod(direction){if(page==='goals'&&goalsView==='growth')date=M.addDays(date,7*direction);else if(page==='goals'){const months=goalLevel==='five'?60:goalLevel==='year'?12:goalLevel==='quarter'?3:goalLevel==='month'?1:0;date=months?M.shiftMonth(date,months*direction):M.addDays(date,7*direction);goalFocus=null;}else date=page==='agenda'&&view==='month'?M.shiftMonth(date,direction):M.addDays(date,(view==='week'&&page==='agenda'?7:1)*direction);render();}
function resizeLine(input){if(!input)return;input.style.height='auto';input.style.height=Math.max(24,input.scrollHeight)+'px';}
function draftKey(form){return [form.dataset.quickDate||'',form.dataset.quickTime||'',form.dataset.quickQuadrant||2].join('|');}
function focusQuick(d,time='',quadrant=2){const form=document.querySelector(`.inline-task[data-quick-date="${CSS.escape(d||'')}"][data-quick-time="${CSS.escape(time)}"][data-quick-quadrant="${quadrant}"]`);form?.querySelector('input')?.focus({preventScroll:true});}
function focusNewLine(){if(view==='month'){view='day';render();}if(view==='day'){focusQuick(date,'09:00');const input=document.querySelector(`.inline-task[data-quick-time="09:00"] input`);input?.scrollIntoView({block:'center',behavior:'smooth'});}else if(view==='matrix')focusQuick(date,'',2);else focusQuick(date);}
function lineError(input,message){const wrap=input.closest('.mention-wrap');if(wrap){wrap.querySelector('.line-error').textContent=message;wrap.classList.toggle('has-error',!!message);}input.setAttribute('aria-invalid',message?'true':'false');}
function applyParsed(task,parsed){if(task.company!==parsed.company){task.projectId='';task.goalId=null;}task.company=parsed.company;if(parsed.explicitProject)task.projectId=parsed.projectId;task.title=parsed.title;if(parsed.executor){if(task.executor!==parsed.executor)task.assignee='';task.executor=parsed.executor;}task.updatedAt=new Date().toISOString();}
function refreshLine(task){document.querySelectorAll(`[data-task-id="${CSS.escape(task.id)}"]`).forEach(row=>{row.setAttribute('style',companyStyle(task.company));const template=document.createElement('template');template.innerHTML=taskCard(task);row.querySelector('.line-meta').innerHTML=template.content.querySelector('.line-meta').innerHTML;const input=row.querySelector('.line-title');input.value=task.title;input.setAttribute('aria-label','Editar tarea: '+task.title);resizeLine(input);row.querySelector('[data-open-task]').setAttribute('aria-label','Notas y detalles: '+task.title);row.querySelector('[data-task-check]').setAttribute('aria-label','Completar '+task.title);});}
function commitInline(input){const task=state.tasks.find(t=>t.id===input.dataset.inlineTask);if(!task||input.value===task.title)return true;const parsed=M.parseEntry(input.value,state,task.company),error=(parsed.repeat&&task.seriesId?'Esta tarea ya se repite. Edita solo el texto o abre su tarjeta.':parsed.repeat&&!task.date?'Asigna una fecha en la tarjeta antes de repetir.':'')||parsed.error||(!parsed.title?'Escribe una tarea; no se borrará el renglón anterior.':'');if(error){lineError(input,error);return false;}applyParsed(task,parsed);if(parsed.repeat)M.addRecurrence(state,task,parsed.repeat,uid());lineError(input,'');save();refreshLine(task);if(parsed.unknown.length)notify('Etiqueta sin reconocer: '+parsed.unknown.join(', ')+'. Se conservó como texto.');return true;}
function createEntry(form){const input=form.querySelector('input'),parsed=M.parseEntry(input.value,state,company==='all'?'PER':company);const error=(state.tasks.length>=20000?'La libreta alcanzó el límite local. Exporta una copia antes de añadir más.':'')||parsed.error||(!parsed.title?'Escribe qué vas a hacer.':'');if(error){lineError(input,error);input.focus();return;}const stamp=new Date().toISOString(),goal=state.goals.find(g=>g.id===agendaGoal&&g.company===parsed.company);const task={id:uid(),title:parsed.title,company:parsed.company,projectId:parsed.projectId||'',goalId:goal?.id||null,date:form.dataset.quickDate||null,time:form.dataset.quickTime||'',duration:30,quadrant:+form.dataset.quickQuadrant||2,priority:false,executor:parsed.executor||(view==='matrix'&&executorFilter!=='all'?executorFilter:'self'),assignee:'',calendarId:state.calendars.find(c=>c.visible)?.id||'main',done:false,decision:false,notes:'',createdAt:stamp,updatedAt:stamp,origin:'Escrita en la libreta · Sin acciones externas'};state.tasks.push(task);if(parsed.repeat)M.addRecurrence(state,task,parsed.repeat,uid());entryDrafts.delete(draftKey(form));const d=task.date,time=task.time,q=task.quadrant;save();render();focusQuick(d,time,q);if(parsed.unknown.length)notify('Etiqueta sin reconocer: '+parsed.unknown.join(', ')+'. Se conservó como texto.');}
function mentionAt(input){const before=input.value.slice(0,input.selectionStart),match=before.match(/(^|\s)([@#])([\p{L}\p{N}_.-]*)$/u);return match?{prefix:match[2],query:match[3],start:before.length-match[3].length-1,end:input.selectionStart}:null;}
function closeMentions(){document.querySelectorAll('.mention-menu').forEach(e=>e.remove());}
function showMentions(input){closeMentions();const token=mentionAt(input);if(!token)return;const items=token.prefix==='@'?M.mentionCatalog(state).filter(x=>!x.closed).map(x=>({value:'@'+x.handle,title:x.title,kind:x.kind==='company'?'Negocio':'Proyecto'})):[{value:'#ia',title:'IA · Sin ejecutar',kind:'Responsable'},{value:'#humano',title:'Humano · Por definir',kind:'Responsable'},{value:'#yo',title:'Yo',kind:'Responsable'}];const unique=[...new Map(items.filter(x=>M.handle(x.value).startsWith(M.handle(token.query))).map(x=>[x.value,x])).values()].slice(0,7);if(!unique.length)return;const menu=document.createElement('div');menu.className='mention-menu';menu.dataset.active='-1';menu.innerHTML=unique.map(x=>`<button type="button" data-insert-mention="${esc(x.value)}"><strong>${esc(x.value)}</strong><span>${esc(x.title)} · ${x.kind}</span></button>`).join('')+'<small>Tab completa · Enter guarda el renglón</small>';input.closest('.mention-wrap').append(menu);}
function insertMention(button){const wrap=button.closest('.mention-wrap'),input=wrap.querySelector('.line-title')||wrap.querySelector('input'),token=mentionAt(input);if(!token)return;const text=button.dataset.insertMention+' ';input.value=input.value.slice(0,token.start)+text+input.value.slice(token.end);const cursor=token.start+text.length;closeMentions();input.focus();input.setSelectionRange(cursor,cursor);if(input.matches('textarea'))resizeLine(input);const form=input.closest('.inline-task');if(form)entryDrafts.set(draftKey(form),input.value);}
document.addEventListener('mousedown',e=>{if(e.target.closest('[data-insert-mention]'))e.preventDefault();});
document.addEventListener('focusout',e=>{if(e.target.matches('.line-title'))commitInline(e.target);if(!e.relatedTarget?.closest('.mention-menu'))closeMentions();});
document.addEventListener('input',e=>{if(e.target.matches('.line-title,.notebook-add input')){if(e.target.matches('textarea'))resizeLine(e.target);const form=e.target.closest('.inline-task');if(form)entryDrafts.set(draftKey(form),e.target.value);lineError(e.target,'');showMentions(e.target);}});
document.addEventListener('keydown',e=>{const input=e.target;if(!input.matches('.line-title,.notebook-add input'))return;if(e.isComposing)return;const menu=input.closest('.mention-wrap').querySelector('.mention-menu'),buttons=menu?[...menu.querySelectorAll('button')]:[];if(menu&&['ArrowDown','ArrowUp','Tab'].includes(e.key)){e.preventDefault();if(e.key==='Tab'){insertMention(buttons[Math.max(0,+menu.dataset.active)]);return;}let index=+menu.dataset.active;index=(index+(e.key==='ArrowDown'?1:-1)+buttons.length)%buttons.length;menu.dataset.active=index;buttons.forEach((b,i)=>b.classList.toggle('selected',i===index));return;}if(menu&&e.key==='Enter'&&+menu.dataset.active>=0){e.preventDefault();insertMention(buttons[+menu.dataset.active]);return;}if(e.key==='Escape'){e.preventDefault();if(menu){closeMentions();return;}if(input.dataset.inlineTask){const task=state.tasks.find(t=>t.id===input.dataset.inlineTask);input.value=task?.title||input.value;resizeLine(input);lineError(input,'');input.blur();}return;}if(e.key==='Enter'&&!e.shiftKey){e.preventDefault();closeMentions();if(input.dataset.inlineTask){if(commitInline(input)){const row=input.closest('[data-drop-date]');if(row)focusQuick(row.dataset.dropDate,row.dataset.dropTime||'',+row.querySelector('.inline-task')?.dataset.quickQuadrant||2);else input.blur();}}else createEntry(input.closest('form'));}});
document.addEventListener('click',event=>{const b=event.target.closest('button');if(!b)return;
  if(b.classList.contains('close-dialog')){b.closest('dialog').close();return;}
  if(b.dataset.page){page=b.dataset.page;goalFocus=null;agendaGoal=null;goalsView='structure';render();}
  else if(b.dataset.goalsView){goalsView=b.dataset.goalsView;render();}
  else if(b.dataset.view){view=b.dataset.view;render();}
  else if(b.dataset.mode){mode=b.dataset.mode;render();}
  else if(b.dataset.slotMinutes){slotMinutes=+b.dataset.slotMinutes;render();}
  else if(b.dataset.insertMention){insertMention(b);}
  else if(b.dataset.company){company=b.dataset.company;goalFocus=null;agendaGoal=null;render();}
  else if(b.dataset.openTask)openTask(b.dataset.openTask);
  else if(b.dataset.openDay){date=b.dataset.openDay;view='day';page='agenda';render();}
  else if(b.dataset.openDate){date=b.dataset.openDate;render();}
  else if(b.dataset.addDate)openTask(null,{date:b.dataset.addDate,time:b.dataset.addTime});
  else if(b.dataset.openGoal){page='goals';goalFocus=b.dataset.openGoal;render();}
  else if(b.dataset.editGoal)openGoalForm(b.dataset.editGoal);
  else if(b.dataset.level){goalLevel=b.dataset.level;goalFocus=null;render();}
  else if(b.dataset.goalRoot){goalFocus=null;render();}
  else if(b.dataset.goalAgenda){const g=state.goals.find(g=>g.id===b.dataset.goalAgenda);if(g){agendaGoal=g.id;company=g.company;date=g.level==='five'||g.level==='year'||g.level==='quarter'?TODAY:g.start;page='agenda';view='week';render();}}
  else if(b.dataset.addGoalTask){const goal=state.goals.find(g=>g.id===b.dataset.addGoalTask);if(goal){company=goal.company;openTask(null,{goalId:goal.id,date:goal.start});}}
  else if(b.dataset.habitDay){date=b.dataset.habitDay;render();}
  else if(b.dataset.addHabit)openHabit(b.dataset.addHabit);
  else if(b.dataset.editCompany)openCompany(b.dataset.editCompany);
  else if(b.id==='add-main'||b.id==='add-goal-card'){if(page==='goals')openGoalForm();else if(page==='habits')openHabit();else if(page==='agenda')focusNewLine();else openTask(null,{decision:page==='decisions'});}
  else if(b.id==='previous-period')changePeriod(-1);
  else if(b.id==='next-period')changePeriod(1);
  else if(b.id==='go-today'){date=TODAY;render();}
  else if(b.id==='assistant-button')$('#assistant-dialog').showModal();
  else if(b.id==='connections-button')openConnections();
  else if(b.id==='assistant-connections'){$('#assistant-dialog').close();openConnections();}
  else if(b.id==='open-decisions'||b.id==='mobile-decisions'){page='decisions';render();}
  else if(b.id==='new-decision')openTask(null,{decision:true});
  else if(b.id==='print-button')window.print();
  else if(b.id==='clear-goal-filter'){agendaGoal=null;render();}
  else if(b.id==='task-complete')saveTask(true);
  else if(b.id==='add-company')openCompany();
  else if(b.id==='open-repeats')openRepeats();
  else if(b.dataset.stopRepeat){M.stopRecurrence(state,b.dataset.stopRepeat,TODAY);save();if($('#repeats-dialog').open)openRepeats(false);if($('#task-dialog').open)configureRepeatCard(state.tasks.find(t=>t.id===$('#task-id').value));render();notify('Repetición detenida desde hoy. Se conserva el historial y lo completado.');}
  else if(b.id==='open-projects')openProjects();
  else if(b.id==='add-project-list')openProject();
  else if(b.dataset.editProject)openProject(b.dataset.editProject);
  else if(b.dataset.toggleProject){const p=state.projects.find(p=>p.id===b.dataset.toggleProject);if(p){p.status=p.status==='completed'?'active':'completed';p.closedAt=p.status==='completed'?new Date().toISOString():null;save();openProjects(false);render();}}
  else if(b.id==='open-import')openImport();
  else if(b.id==='confirm-import')confirmImport();
  else if(b.id==='export-copy')exportCopy();
  else if(b.dataset.suggestHabit){const suggestion=M.routineSuggestions(state)[+b.dataset.suggestHabit];if(suggestion){openHabit('anytime');$('#habit-title').value=suggestion.title;$('#habit-company').value=suggestion.company;$('#habit-time').value=M.formatTime12(suggestion.time);document.querySelectorAll('#habit-days input').forEach(e=>e.checked=suggestion.days.includes(+e.value));}}
  else if(b.id==='add-calendar'||b.id==='mobile-add-calendar'){$('#calendar-form').reset();$('#calendar-dialog').showModal();$('#calendar-title').focus();}
  else if(b.id==='demo-info')$('#info-dialog').showModal();
  else if(b.id==='reset-button'){$('#info-dialog').close();$('#reset-dialog').showModal();}
  else if(b.id==='confirm-reset'){state=M.upgrade(M.seed(TODAY));company='all';agendaGoal=null;goalFocus=null;date=TODAY;save();$('#reset-dialog').close();render();notify('Datos de ejemplo reiniciados.');}
});
document.addEventListener('change',event=>{const e=event.target;
  if(e.id==='executor-filter'){executorFilter=e.value;render();}
  else if(e.dataset.taskCheck){const t=state.tasks.find(t=>t.id===e.dataset.taskCheck);if(t){recordCompletion(t,e.checked);save();render();}}
  else if(e.dataset.calendarVisible){const c=state.calendars.find(c=>c.id===e.dataset.calendarVisible);if(c){c.visible=e.checked;save();render();}}
  else if(e.dataset.habitCheck){state.habitChecks[`${e.dataset.habitDate}|${e.dataset.habitCheck}`]=e.checked;save();render();}
  else if(e.id==='mobile-company'){if(e.value==='__new__'){e.value=company;openCompany();}else if(e.value==='__projects__'){e.value=company;openProjects();}else if(e.value==='__import__'){e.value=company;openImport();}else if(e.value==='__repeats__'){e.value=company;openRepeats();}else{company=e.value;goalFocus=null;agendaGoal=null;render();}}
  else if(e.id==='task-company')updateTaskFields();
  else if(e.id==='task-goal')updateGoalTrail();
  else if(e.id==='task-project'&&e.value==='__new__'){e.value='';openProject();}
  else if(e.id==='task-decision')$('#task-kind-label').textContent=e.value==='1'?'Decisión':'Tarea';
  else if(e.id==='goal-company'||e.id==='goal-level'){parentOptions();if(e.id==='goal-level'){const [start,end]=M.periodBounds(e.value,date);$('#goal-start').value=start;$('#goal-end').value=end;}}
});
document.addEventListener('input',event=>{const key=event.target.dataset.noteKey;if(key){state.dayNotes[key]=event.target.value;save();}});
document.addEventListener('submit',event=>{const form=event.target;
  if(form.classList.contains('inline-task')){event.preventDefault();createEntry(form);}
  else if(form.id==='task-form'){event.preventDefault();saveTask();}
  else if(form.id==='goal-form'){event.preventDefault();const id=$('#goal-id').value,old=state.goals.find(g=>g.id===id);const goal={id:id||uid(),title:$('#goal-title').value.trim(),company:$('#goal-company').value,level:$('#goal-level').value,parentId:$('#goal-parent').value||null,start:$('#goal-start').value,end:$('#goal-end').value,notes:$('#goal-notes').value,example:false};const error=M.parentError(state.goals,goal,state.companies);if(error){$('#goal-error').textContent=error;return;}if(old)Object.assign(old,goal);else state.goals.push(goal);save();$('#goal-dialog').close();render();}
  else if(form.id==='habit-form'){event.preventDefault();const title=$('#habit-title').value.trim(),time=M.parseTime12($('#habit-time').value),days=[...document.querySelectorAll('#habit-days input:checked')].map(e=>+e.value);if(time===null){$('#habit-error').textContent='Escribe la hora con AM o PM; por ejemplo, 9:30 AM.';return;}if(!title||!days.length){$('#habit-error').textContent='Escribe el hábito y elige al menos un día.';return;}state.habits.push({id:uid(),title,group:$('#habit-group').value,time,company:$('#habit-company').value,days});save();$('#habit-dialog').close();render();}
  else if(form.id==='calendar-form'){event.preventDefault();const title=$('#calendar-title').value.trim();if(!title)return;state.calendars.push({id:'cal-'+uid(),title,visible:true});save();$('#calendar-dialog').close();render();notify('Calendario añadido solo en esta demo.');}
  else if(form.id==='company-form'){event.preventDefault();const name=$('#company-name').value.trim();if(!name){notify('Escribe el nombre del negocio.');return;}const id=$('#company-id').value||'B-'+uid(),[color,bg]=palette[+new FormData(form).get('color')];state.companies[id]={name,role:$('#company-role').value.trim(),color,bg,platform:$('#company-platform').value.trim(),url:$('#company-url').value.trim(),context:$('#company-context').value.trim()};company=id;goalFocus=null;agendaGoal=null;save();$('#company-dialog').close();render();notify('Negocio guardado en la demo.');}
  else if(form.id==='project-form'){event.preventDefault();const title=$('#project-title').value.trim(),id=$('#project-id').value,old=state.projects.find(p=>p.id===id),companyId=$('#project-company').value;if(!title){notify('Escribe el nombre del proyecto.');return;}if(old&&old.company!==companyId&&state.tasks.some(t=>t.projectId===id)){notify('Este proyecto tiene historial. Conserva su negocio y crea otro si lo necesitas.');return;}const project={id:id||uid(),title,company:companyId,status:$('#project-status').value};if(old)Object.assign(old,project);else state.projects.push(project);save();$('#project-dialog').close();if(projectReturn==='task'){updateTaskFields();if($('#task-company').value===project.company)$('#task-project').value=project.id;}else{render();openProjects();}notify('Proyecto guardado. Su historial se conserva.');}
});
document.addEventListener('keydown',event=>{if(event.key.toLowerCase()==='n'&&!event.ctrlKey&&!event.metaKey&&!event.altKey&&!event.repeat&&!['INPUT','TEXTAREA','SELECT'].includes(event.target.tagName)&&!event.target.isContentEditable&&!document.querySelector('dialog[open]')){event.preventDefault();if(page==='agenda')focusNewLine();else openTask();}});
document.addEventListener('dragstart',event=>{const t=event.target.closest('[data-task-id]');if(t&&event.dataTransfer){event.dataTransfer.setData('text/plain',t.dataset.taskId);event.dataTransfer.effectAllowed='move';}});
document.addEventListener('dragover',event=>{const drop=event.target.closest('[data-drop-date]');if(drop){event.preventDefault();drop.classList.add('drag-over');}});
document.addEventListener('dragleave',event=>{const d=event.target.closest('.drag-over');if(d&&!d.contains(event.relatedTarget))d.classList.remove('drag-over');});
document.addEventListener('dragend',()=>document.querySelectorAll('.drag-over').forEach(e=>e.classList.remove('drag-over')));
document.addEventListener('drop',event=>{const drop=event.target.closest('[data-drop-date]');if(!drop)return;event.preventDefault();const task=state.tasks.find(t=>t.id===event.dataTransfer?.getData('text/plain'));if(!task)return;const candidate={...task,date:drop.dataset.dropDate,time:drop.dataset.dropTime||task.time};const error=M.priorityError(state.tasks,candidate);if(error){notify(error);drop.classList.remove('drag-over');return;}Object.assign(task,candidate);save();render();});
function openProjects(show=true){$('#projects-list').innerHTML=state.projects.map(p=>`<div class="project-row"><div><strong>${esc(p.title)}</strong><small>${tag(p.company)} · ${p.status==='completed'?'Terminado':p.status==='paused'?'En pausa':'Activo'} · ${state.tasks.filter(t=>t.projectId===p.id).length} tareas</small></div><div><button class="text-button" data-edit-project="${esc(p.id)}">Editar</button><button class="quiet-button" data-toggle-project="${esc(p.id)}">${p.status==='completed'?'Reactivar':'Terminar'}</button></div></div>`).join('')||'<p class="empty">Añade tu primer proyecto.</p>';if(show)$('#projects-dialog').showModal();}
function openImport(){pendingImport=null;$('#import-file').value='';$('#import-preview').innerHTML='';$('#confirm-import').disabled=true;$('#import-dialog').showModal();}
function confirmImport(){if(!pendingImport?.rows.length)return;if(state.tasks.length+pendingImport.rows.length>20000){notify('Esta importación supera el límite de 20.000 tareas locales.');return;}try{localStorage.setItem(KEY+'.before-import',JSON.stringify(state));}catch{notify('No hay espacio para guardar una copia previa. No se importó nada.');return;}const origin='Importación manual: '+pendingImport.filename,stamp=new Date().toISOString();state.tasks.push(...pendingImport.rows.map(t=>({...t,id:uid(),calendarId:state.calendars.find(c=>c.visible)?.id||'main',createdAt:stamp,updatedAt:stamp,origin})));const count=pendingImport.rows.length;pendingImport=null;save();$('#import-dialog').close();executorFilter='all';render();notify(count+' tareas importadas. No se reemplazaron tareas existentes.');}
function exportCopy(){const blob=new Blob([JSON.stringify({exportedAt:new Date().toISOString(),application:'Juan Pablo Merizalde · Libreta',state},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='juan-pablo-merizalde-'+TODAY+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
