$('#import-file').addEventListener('change',async e=>{const file=e.target.files?.[0];pendingImport=null;$('#confirm-import').disabled=true;$('#import-preview').innerHTML='';if(!file)return;try{if(file.size>1000000)throw Error('Máximo 1 MB por archivo.');const preview=M.prepareImport(await file.text(),state);pendingImport={...preview,filename:file.name};$('#import-preview').innerHTML=`<p>${preview.rows.length} nuevas · ${preview.duplicates} duplicadas · ${preview.issues.length} con errores</p>${preview.rows.slice(0,5).map(t=>`<div class="import-row"><strong>${esc(t.title)}</strong><small>${tag(t.company)} · ${t.date?esc(t.date):'Sin fecha'} ${esc(M.formatTime12(t.time))}</small></div>`).join('')}${preview.issues.length?'<details><summary>Revisar errores</summary>'+preview.issues.slice(0,20).map(x=>`<p class="form-error">Fila ${x.row}: ${esc(x.error)}</p>`).join('')+'</details>':''}`;$('#confirm-import').disabled=!preview.rows.length;$('#confirm-import').textContent='Importar '+preview.rows.length+' válidas';}catch(error){$('#import-preview').innerHTML='<p class="form-error">'+esc(error.message)+'</p>';}});
