function repeatFromCard(){const value=$('#task-repeat').value;if(!value)return null;const [unit,count]=value.split(':');return {unit,interval:+count};}
function configureRepeatCard(task){
 const rule=state.recurrences.find(r=>r.id===task?.seriesId),select=$('#task-repeat');select.querySelectorAll('[data-custom-repeat]').forEach(o=>o.remove());const value=rule?rule.unit+':'+rule.interval:'';if(rule&&![...select.options].some(o=>o.value===value)){const option=new Option(M.repeatLabel(rule),value);option.dataset.customRepeat='true';select.add(option);}select.value=value;select.disabled=!!rule;
 $('#task-repeat-info').innerHTML=rule?'<span>'+esc(M.repeatLabel(rule))+' · Desde '+esc(rule.start)+(rule.stoppedFrom?' · Detenida desde '+esc(rule.stoppedFrom):'')+'</span><p>Editar texto, notas, hora o responsable cambia solo esta fecha.</p>'+(!rule.stoppedFrom?'<button type="button" class="text-button" data-stop-repeat="'+esc(rule.id)+'">Dejar de repetir desde hoy</button>':''):'<p>Cada fecha tiene su propio chulo. No crea pagos ni ejecuta agentes.</p>';
}
